package main
import("encoding/json";"crypto/sha256";"fmt";"os";"io";"path/filepath";"strings")
func main(){root:="/home/isucon/webapp/state";if b,e:=os.ReadFile(filepath.Join(root,"CURRENT"));e==nil{root=filepath.Join(root,strings.TrimSpace(string(b)))};f,e:=os.Open(filepath.Join(root,"journal.jsonl"));if e!=nil{panic(e)};defer f.Close();dec:=json.NewDecoder(f);counts:=map[string]int{};unique:=map[[32]byte]int{};var imageBytes int64;for{var v struct{Kind string;Image []byte};e=dec.Decode(&v);if e==io.EOF||e==io.ErrUnexpectedEOF{break};if e!=nil{panic(e)};counts[v.Kind]++;if v.Kind=="icon"{unique[sha256.Sum256(v.Image)]=len(v.Image);imageBytes+=int64(len(v.Image))}};var uniqBytes int64;for _,n:=range unique{uniqBytes+=int64(n)};fmt.Println("events",counts,"image_bytes",imageBytes,"distinct_images",len(unique),"distinct_bytes",uniqBytes)}
